 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class BSTIterator {
private:
    stack<TreeNode*> stk;

public:
    BSTIterator(TreeNode* root) {
        while (root) {
            stk.push(root);
            root = root->left;
        }
    }

    int next() {
        TreeNode* res = stk.top();
        stk.pop();
        TreeNode* cur = res->right;
        while (cur) {
            stk.push(cur);
            cur = cur->left;
        }
        return res->val;
    }

    bool hasNext() {
        return !stk.empty();
    }
};

