class BSTIterator(root: TreeNode?) {
    private val stack = ArrayDeque<TreeNode>()

    init {
        var current = root
        while (current != null) {
            stack.addLast(current)
            current = current.left
        }
    }

    fun next(): Int {
        val res = stack.removeLast()
        var cur = res.right
        while (cur != null) {
            stack.addLast(cur)
            cur = cur.left
        }
        return res.`val`
    }

    fun hasNext(): Boolean {
        return stack.isNotEmpty()
    }
}

